import Foundation

private typealias E = EvidenceSeed

/// Everyday cases, written with SmallCases: the offenses that fill a real county's docket.
extension StoryCases {
    static let batchAU: [CaseTemplate] = [constructionDumping, copperWireStripping, scratchOffTheft, neighborDogShot, weddingDriveImpaired, busPhoneSnatch, seniorPhoneScam, badRentCheck, skateparkScuffle, campusThreat, courthouseKnife, occupiedHouseNight, tireIronAssault, photoExtortion, inspectorBribe, investmentClub, payrollClerkTheft, contractKillingPlot, boatCrashFatal, fentanylStash, unlockedGunToddler]

    static let constructionDumping = SmallCases.make(
        key: "story.constructionDumping",
        category: .property,
        headlines: ["Roofing Debris Dumped on Farmland Overnight", "Landowner Finds Shingles and Nails Across Pasture"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, farmland, causing damage of $3,600, on {DATE}.",
        ages: 25...60,
        victim: true,
        summary: "{V} found a pasture covered with roofing shingles, nails, and drywall on {DATE}. A delivery slip in the pile bore {D}'s roofing company's name. Cleanup cost $3,600. {DL} says a subcontractor dumped it without permission.",
        state: [E(.document, 3, "Delivery Slip", "A slip from {D}'s roofing company."), E(.physical, 2, "Debris", "Shingles matching a recent job.", .search)],
        defense: [E(.statement, 1, "Subcontractor", "{DL} says a subcontractor dumped it.")],
        role: "Landowner",
        exam: [.direct("What did you find on {DATE}?", "\"A pasture on my farm was covered with roofing shingles, nails, and chunks of drywall. It was a mess, and my cattle graze there.\""), .direct("How did it get there?", "\"Somebody dumped it from a truck overnight. There were tire marks near the gate and a trail through the grass.\""), .direct("What did you find in the pile?", "\"A delivery slip with the name of {D}'s roofing company on it. That is how I got a name to start with.\""), .direct("What did you do?", "\"I called the sheriff's office and photographed everything. I made a list of what was there, and a deputy came out.\""), .direct("What did the cleanup cost?", "\"$3,600. I hired a crew and a dump trailer, and I lost two days of use of the field.\""), .direct("Why does the debris matter to you?", "\"The nails are dangerous for cattle, and I had to sweep the field with a magnet. I'd never allow anyone to dump on my land.\""), .cross("Isn't it true the slip only shows the company name?", "\"Yes. The slip has the company's name and not who was driving. I don't know who dumped it.\""), .cross("Did you see the truck?", "\"No. I was asleep. I found the pile in the morning.\""), .cross("Did you speak to {D}?", "\"I called the company. {D} said a subcontractor must have done it and that {D} didn't know about it.\""), .cross("Do the shingles match a recent job?", "\"A deputy compared them to a recent roofing job, and the color matched. It's a common shingle, though.\""), .cross("Is it possible someone else used the slip?", "\"It's possible. I don't know how slips are handled at the company.\"")],
        theory: ("{D} dumped debris on farmland.", "A rogue subcontractor."),
        allocution: "\"It came from my jobs. I'll pay.\"",
        truths: ("{DL} had a truck on the road that night per a camera.", "The slip was a template shared by three subcontractors who also hauled for {DL}."),
        defendant: [.direct("Tell the jury about your roofing company.", "\"I run a roofing business with a few crews. We tear off old shingles and put new ones on, and we haul the debris to the landfill.\""), .direct("Did you dump on {V}'s land?", "\"No. I've never been to that pasture. I pay dump fees at the landfill every week.\""), .direct("How could the slip end up there?", "\"The slip is a template I share with a few subcontractors who haul for me. Any of them could have used it.\""), .direct("Do you know who dumped it?", "\"I'm trying to find out. I've asked each of my subcontractors, and no one has admitted it yet.\""), .direct("Was your truck on that road that night?", "\"I drove that road because it's a shortcut from a job. That doesn't mean I stopped.\""), .direct("Will you pay for the cleanup?", "\"If I'm shown it was mine, I'll pay. I don't want to leave a neighbor with a mess.\""), .cross("The slip has your company's name on it?", "\"Yes. It's my template, and I understand why it points to me.\""), .cross("A camera put your truck on the road that night, didn't it?", "\"It did. I drive that road often, and I didn't stop at that field.\""), .cross("The shingles matched a recent job?", "\"They match a job I did, yes. But I have three subcontractors who hauled for me on that job.\""), .cross("You can't name the subcontractor?", "\"Not yet. I suspect one of them but can't prove it, and I won't accuse without proof.\""), .cross("Dumping at a landfill costs money, doesn't it?", "\"Yes, it does, and that's an incentive to cheat. I'm not that kind of businessperson.\"")],
        openings: ("{V} found a pasture covered with roofing shingles, nails, and drywall, and a delivery slip in the pile bore the name of {D}'s roofing company. Cleanup cost $3,600, and a camera put {D}'s truck on the road that night.", "{D}'s slip is a template shared with three subcontractors who also haul for {D}, and {D} never went to that field. The defense says the State has a name on a piece of paper and nothing placing {D} at the dumping."),
        closings: ("The slip bears {D}'s company's name, the shingles match {D}'s job, and {D}'s truck was on that road. A landowner paid $3,600 to clean up the mess.", "A shared template, three subcontractors who haul for {D}, and no one who saw {D} dump anything. A name on a slip is not proof of who unloaded the truck."),
        timeline: [(0, "Night: a truck stops on the road."), (1, "{V} finds the debris."), (2, "The delivery slip is found.")],
        identified: "A delivery slip.",
        mood: .wantsConviction)

    static let copperWireStripping = SmallCases.make(
        key: "story.copperWireStripping",
        category: .property,
        headlines: ["Copper Wiring and Pipes Ripped From Vacant House", "Scrap Yard Records Show Repeat Seller"],
        law: "felonyLarceny",
        threshold: 6,
        spec: "Stole copper wiring and pipe valued at $6,200 belonging to {V}, on {DATE}.",
        ages: 20...55,
        victim: true,
        summary: "{V}, owner of a vacant rental house, found the walls opened and all copper pipe and wiring gone on {DATE}, worth $6,200. A scrap yard had bought stripped copper from {D} twice that week. {DL} says {D.he} collects scrap from job sites.",
        state: [E(.document, 3, "Scrap Receipts", "{D} sold 120 pounds of stripped copper twice that week."), E(.physical, 2, "House", "Walls opened and pipes cut.")],
        defense: [E(.statement, 1, "Job Site Scrap", "{DL} says {D.he} collects scrap from job sites.")],
        role: "Property owner",
        exam: [.direct("What do you own?", "\"A vacant rental house that I was fixing up between tenants. It sat empty for about a month while I waited on repairs.\""), .direct("What did you find on {DATE}?", "\"The interior walls had been opened up, and every copper pipe and all the wiring were gone. The house was gutted.\""), .direct("What was the value of what was taken?", "\"About $6,200 in copper, not counting the damage to the walls and the cost of replacing everything.\""), .direct("When do you think it happened?", "\"Around four days before I found it. A neighbor said the house looked untouched until a few days earlier.\""), .direct("How did {D} come to your attention?", "\"A deputy called scrap yards and learned one had bought stripped copper from {D} twice that week, 120 pounds each time.\""), .direct("What did the house look like inside?", "\"Holes cut through drywall, pipe ends sawed off, and insulation scattered everywhere. It would be thousands to restore.\""), .cross("Isn't it true you did not see anyone enter the house?", "\"Correct. It was vacant and I only found the damage later. I don't know who went in.\""), .cross("Did you know {D}?", "\"No. I'd never met {D}. I don't know of any connection with the house.\""), .cross("Are the cut pipe ends unique to a certain tool?", "\"The deputy said the cuts matched a certain kind of tool, but plenty of people own the same one.\""), .cross("Did you lock the house?", "\"Yes, but the back door lock was old. Someone could have forced it without much trouble.\""), .cross("Is 120 pounds of copper a lot?", "\"It is a decent amount, though it isn't the entire house. I can't say all the copper in my house weighed 240 pounds.\"")],
        defenseRole: "Scrap yard clerk",
        defenseExam: [.direct("What do you do at the scrap yard?", "\"I'm a clerk. I weigh materials, check IDs, pay sellers, and log every sale.\""), .direct("Do you know {D}?", "\"Yes. {D} is a regular who brings in copper and other metals from job sites.\""), .direct("What did {D} sell that week?", "\"Two loads of stripped copper, about 120 pounds each. We logged them with {D}'s ID.\""), .direct("What do you require from a seller?", "\"A photo ID and a signature on the ticket. For large amounts of copper, we ask where it came from.\""), .direct("What did {D} say about the source?", "\"That it came from a demolition job. {D} sometimes brings paperwork, and I think {D} had a contract.\""), .direct("How did {D} behave?", "\"Normal and open. {D} didn't hurry, didn't hide a face, and answered questions.\""), .cross("You can't verify where the copper came from, can you?", "\"Not with certainty. I take the seller's word and the ID, and we log it.\""), .cross("Do thieves ever use their own IDs at your yard?", "\"It happens, but it's less common. Some are careless.\""), .cross("Is stripped copper from a house different from job-site copper?", "\"It can look the same. Stripped copper is stripped copper, and I can't tell the source.\""), .cross("How many other people sell copper here each week?", "\"Dozens. Many of them are contractors, and some are just collectors.\""), .cross("You don't know if {D} had a contract for that specific house?", "\"No. I only know what {D} told me, and I didn't see the contract that week.\"")],
        theory: ("{D} stripped a house of copper.", "Scrap from job sites."),
        allocution: "\"I needed the money.\"",
        truths: ("Cut pipe ends matched {DL}'s tool.", "{DL} held a salvage license and a signed contract for a demolition job two streets away."),
        defendant: [.direct("How do you earn a living?", "\"I salvage metal and scrap from demolition sites and sell it to scrap yards. I've done it for several years.\""), .direct("Where did the copper come from?", "\"From job sites. I had a demolition contract for a house two streets from {V}'s, and the copper came from there.\""), .direct("Do you have a salvage license?", "\"Yes, and a signed contract for the demolition job. I carry copies and gave them to the deputy.\""), .direct("Have you ever been inside {V}'s house?", "\"No. I've driven past it, but I never went in, and I didn't take copper from it.\""), .direct("What tool do you use to cut pipe?", "\"A tubing cutter and a reciprocating saw. They're common tools in my trade, and I use them on every job.\""), .direct("What did you tell the deputy?", "\"That I'd sold copper from my own job and gave the contract. I wasn't hiding anything.\""), .cross("You sold 120 pounds twice in one week, didn't you?", "\"I did, because I was stripping a house and sold as I went. That's how salvage works.\""), .cross("The cut ends on the pipes at {V}'s house match your tool?", "\"I'm told the cuts match a style of tool I own. Many contractors use the same type.\""), .cross("Your job site is two streets away from {V}'s house?", "\"Yes, it's close. I wasn't working at {V}'s, and I never crossed over.\""), .cross("You can't prove the copper you sold came from your job?", "\"I have the contract, but a pile of copper doesn't come with a label. I can show what the job produced.\""), .cross("You sold it within days of the break-in?", "\"The timing is close, I know. That's because I sold everything I stripped within a few days.\"")],
        openings: ("{V} found a vacant rental house with its walls opened and every copper pipe and wire gone, worth $6,200. A scrap yard had bought 120 pounds of stripped copper from {D} twice that week, and the cut ends matched {D}'s tool.", "{D} is a licensed salvager who had a signed demolition contract two streets away. The defense says copper from a job site looks the same as copper from a house, and the State cannot prove where this metal came from."),
        closings: ("Two loads of stripped copper within days of the break-in, pipe ends cut by a tool like {D}'s, and a job two streets away. The copper in {D}'s truck came from somewhere, and the match points to {V}'s house.", "A salvage license, a signed contract, a clerk who knows {D} as a regular, and no one who saw {D} at {V}'s house. Copper is copper, and the State has not proved where it came from."),
        timeline: [(-4, "The vacant house is entered."), (-3, "{DL} sells the first load."), (-1, "{DL} sells the second load."), (0, "{V} finds the opened walls.")],
        identified: "Scrap receipts.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .indifferent)

    static let scratchOffTheft = SmallCases.make(
        key: "story.scratchOffTheft",
        category: .property,
        headlines: ["Man Pulls Roll of Lottery Tickets From Counter Dispenser", "Clerk Chases Customer to Parking Lot"],
        law: "larcenyMerchant",
        spec: "Took lottery tickets valued at $300 from {V}, a convenience store, without paying, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "A customer pulled a roll of scratch-off tickets from a counter dispenser while the clerk turned away on {DATE}. A counter camera showed {D}. {DL} says {D.he} meant to pay and the clerk was ignoring {D.him}.",
        state: [E(.video, 3, "Counter Camera", "{D} pulls a roll and leaves."), E(.physical, 2, "Tickets", "A roll of tickets found in {D}'s car.", .search)],
        defense: [E(.statement, 1, "Ignored", "{DL} says the clerk ignored {D.him}.")],
        role: "Convenience store clerk",
        exam: [.direct("What happened at your counter that afternoon?", "\"I turned to restock the cigarette wall, and when I turned back, {D} had pulled a full roll of scratch-off tickets from the dispenser and was heading for the door.\""), .direct("What was the roll worth?", "\"About $300 in tickets. They are valued at the face price, and we are accountable for every roll.\""), .direct("How was {D} identified?", "\"The counter camera shows {D} pulling the roll and leaving. A roll of tickets was later found in {D}'s car.\""), .direct("Where is the scratch-off dispenser, and how is it displayed?", "\"On the counter next to the register, in a clear plastic dispenser. The rolls are visible but I can't see them from the back of the store.\""), .direct("How did you discover the roll was gone?", "\"About two minutes later I turned around to ring up another customer and saw an empty slot. I checked the camera and saw {D} pull the roll and walk out.\""), .direct("What did you do after you saw the footage?", "\"I called the sheriff's office and sent the video. I also checked the lottery terminal to void the roll's tickets so they couldn't be redeemed.\""), .cross("{D} says you were ignoring {D.him} at the counter, doesn't {D.he}?", "\"I was restocking. I did not know {D} was waiting, and I did not hear anyone ask for service.\""), .cross("{D} might have meant to pay, mightn't {D.he}?", "\"Maybe, but {D} walked out the door with the tickets in hand. There was no stopping at the register.\""), .cross("Did {D} say anything as {D.he} left?", "\"No. I did not hear a word. By the time I turned around, {D} was already outside.\""), .cross("How long was {D} at the counter before you turned away?", "\"About thirty seconds. I'd already said hello, and I wasn't ignoring {D.him}, but I was also helping someone at the register.\""), .cross("Did {D} say anything to you before leaving?", "\"No. I didn't hear {D} say a word, and I didn't see {D} reach for any money.\"")],
        theory: ("{D} took scratch-off tickets.", "A customer who was ignored."),
        allocution: "\"I'm sorry.\"",
        truths: ("{DL} drove away with the roll.", "{DL} had $300 in cash on hand."),
        defendant: [.direct("Did you take the scratch-off tickets?", "\"I picked up the roll, but I meant to pay for it. I was waiting at the counter and no one came to help me.\""), .direct("Why did you leave the store?", "\"I got tired of waiting and I was in a hurry. I walked out to get to my car and planned to come back.\""), .direct("Did you have money to pay for the tickets?", "\"Yes, I had cash on me. About $300. I had enough to pay for them.\""), .direct("Tell us what you were doing in the store.", "\"I'd stopped in to buy a few scratch-offs on my way home. I had cash on me and was ready to pay.\""), .direct("What happened at the counter?", "\"I waited at the register for a couple of minutes. The clerk was busy and I picked up the roll to get their attention.\""), .direct("Why did you leave with the roll?", "\"I was irritated and I wasn't thinking. I walked out intending to come back, and then I just drove.\""), .cross("You drove away with the roll, didn't you?", "\"Yes. I should have gone back right away. I did not, and I know that looks like I took them.\""), .cross("The camera shows you walking straight out. Why not stop at the register?", "\"I was frustrated and I wasn't thinking. I figured I could settle it later.\""), .cross("If you had cash, why not hand it to the clerk?", "\"I didn't see the clerk, and I got impatient. That was a mistake.\""), .cross("You had $300 in cash. Why not put the money on the counter?", "\"I should have. I wasn't thinking clearly, and I was frustrated by the wait.\""), .cross("You drove away with the roll. At what point did you decide to bring it back?", "\"I thought about it as I was driving, and I told myself I'd go back. I never did, and I regret that.\"")],
        openings: ("A convenience store clerk turned away for a moment on {DATE}. When the clerk turned back, {D} had pulled a roll of scratch-off tickets worth $300 from the dispenser and was walking out.", "Weigh the defense proof, which will show that {D} had the cash, waited at the counter, and was ignored. {D} meant to pay for the tickets and never meant to steal them."),
        closings: ("A counter camera, a roll of tickets, and a customer walking straight out the door and driving away. The roll was found in {D}'s car, and nobody paid for it.", "{D} had cash in hand and waited for service that never came. Walking out in frustration is not the same as stealing, and the State must prove intent."),
        timeline: [(0, "2:05 p.m.: the clerk turns away."), (0, "2:06 p.m.: {DL} pulls the roll."), (0, "2:07 p.m.: {DL} leaves.")],
        identified: "A counter camera.",
        mood: .indifferent,
        genders: ["D": .male])

    static let neighborDogShot = SmallCases.make(
        key: "story.neighborDogShot",
        category: .publicOrder,
        headlines: ["Neighbor's Beagle Shot With Air Rifle, Vet Says", "Pellet Wounds Lead to Complaint Between Neighbors"],
        law: "animalCruelty",
        spec: "Maliciously killed or injured an animal belonging to {V} with a pellet rifle, on {DATE}.",
        ages: 25...65,
        victim: true,
        summary: "{V}'s beagle came home with two pellet wounds on {DATE} and needed surgery. {V} had argued with {D} over barking. A neighbor heard pops from {D}'s yard. An air rifle was in {D}'s shed. {DL} says {D.he} fired at squirrels.",
        state: [E(.forensic, 3, "Veterinary Report", "Two pellet wounds; surgery required."), E(.physical, 2, "Air Rifle", "An air rifle and pellets.", .search)],
        defense: [E(.statement, 1, "Squirrels", "{DL} says {D.he} fired at squirrels.")],
        role: "Dog owner",
        exam: [.direct("What happened to your dog?", "\"My beagle came home with two pellet wounds and needed surgery. The vet's report confirms two wounds from pellets.\""), .direct("Had you and {D} had any disagreements?", "\"Yes, about my dog's barking. We argued about it, and {D} was not happy with me.\""), .direct("What did you learn about {D}'s yard?", "\"A neighbor heard pops from {D}'s yard that day. Deputies found an air rifle and pellets in {D}'s shed.\""), .direct("Describe the beagle and how it was injured.", "\"A seven-year-old beagle named for the family. It came home limping, with two small holes in the hindquarters, and the vet found a pellet in each wound.\""), .direct("What did the veterinarian tell you?", "\"The pellets were embedded close to a joint and needed to be removed surgically. The vet said the wounds were consistent with an air rifle at close range.\""), .direct("What did your neighbor hear that day?", "\"A neighbor heard two or three pops from {D}'s yard in the afternoon and thought it was a nail gun. The neighbor didn't see anything.\""), .cross("{D} says the rifle was for squirrels, doesn't {D.he}?", "\"That is what {D} says. But the wounds were at dog height, not squirrel height.\""), .cross("No one saw {D} shoot the dog, did they?", "\"No. No one saw it. All I know is the argument, the pops, and the rifle.\""), .cross("Did your dog get out of your yard that day?", "\"Yes, sometimes the dog gets out. I cannot say where the dog went before coming home.\""), .cross("Did the vet recover the pellets, and were they tested?", "\"Yes. The vet saved them and a deputy took them for comparison, but I don't know what the lab concluded beyond what I was told.\""), .cross("Did your dog ever go into {D}'s yard?", "\"Sometimes, when the gate was left open. I'd told {D} I was sorry about it, and I thought we had settled it.\"")],
        theory: ("{D} shot a neighbor's dog.", "Shots at squirrels."),
        allocution: "\"I'm sorry about what I did to your dog.\"",
        truths: ("Pellets in the dog matched those in {DL}'s shed.", "The beagle had been cut earlier by a barbed-wire fence, a vet's old note shows."),
        defendant: [.direct("Did you shoot {V}'s dog?", "\"No. I did not shoot the dog. I would never hurt an animal.\""), .direct("Why do you own an air rifle?", "\"I use it for squirrels. They get into my garden and the attic, and an air rifle is quiet.\""), .direct("What about the argument over barking?", "\"It was just a neighbor dispute. I was annoyed, but I did not take it out on the dog.\""), .direct("Describe the squirrels for the jury.", "\"They get into my attic and chew through the wires. I shoot them with a pellet rifle from the porch when I see them on the fence.\""), .direct("What were you doing on the afternoon in question?", "\"Shooting at squirrels from my back steps. I fired three or four pellets, and I never saw a dog in my yard.\""), .direct("Why did you text about the dog?", "\"It was a joke. I said the dog would get what was coming to it after it barked for hours, and I didn't mean it.\""), .cross("You sent a text about the dog, didn't you?", "\"It was a joke. I said something dumb in frustration, but I did not mean it.\""), .cross("The pellets in the dog match the pellets in your shed, don't they?", "\"They are common pellets. Anyone with an air rifle would have them.\""), .cross("The wounds were at dog height. How do you explain that?", "\"I do not know. The dog could have been hurt by the fence or something else.\""), .cross("Pellets recovered from the dog match those in your shed. Is that a coincidence?", "\"They're a common brand. A lot of people in the area use the same pellets for squirrel control.\""), .cross("You argued with {V} about barking and then the dog was shot. Isn't that a motive?", "\"I was annoyed, but I wouldn't hurt an animal over it. I never shot the dog.\"")],
        openings: ("A beagle came home with two pellet wounds and needed surgery. The owner had argued with {D} over barking, a neighbor heard pops from {D}'s yard, and an air rifle was in {D}'s shed.", "Jurors will hear that {D} shot only at squirrels and never touched the dog. No one saw a shot, and the injuries have other explanations."),
        closings: ("An argument over barking, pops from {D}'s yard, an air rifle and pellets in the shed, and two pellet wounds in a dog. The pieces fit one story.", "Nobody saw {D} shoot that dog. An air rifle for squirrels and a neighborhood dispute are not proof. The State asks you to guess, and that is not enough."),
        timeline: [(-14, "The barking dispute."), (0, "Afternoon: pops from {DL}'s yard."), (0, "Evening: the dog comes home wounded.")],
        identified: "A veterinary report and pellets.",
        mood: .wantsConviction,
        impact: "Our dog won't go outside.")

    static let weddingDriveImpaired = SmallCases.make(
        key: "story.weddingDriveImpaired",
        category: .traffic,
        headlines: ["Driver Stopped With Revoked License After Wedding Reception", "Breath Test Reads 0.10 at Roadside"],
        law: "dwlrImpaired",
        threshold: 6,
        spec: "Operated a motor vehicle on a highway while {D.his} license was revoked for impaired driving and while impaired, on {DATE}.",
        ages: 25...60,
        victim: false,
        summary: "A deputy stopped {D} on {DATE} after a reception for swerving. {D}'s license was revoked for a prior DWI. A roadside test read 0.10. {DL} says a friend was supposed to drive and left.",
        state: [E(.forensic, 3, "Breath Test", "0.10 at the roadside."), E(.document, 3, "DMV Record", "License revoked for a prior DWI.")],
        defense: [E(.statement, 1, "Friend Left", "{DL} says a friend was supposed to drive.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you see that led to the stop?", "\"After a wedding reception, I saw {D}'s car swerving across the lane. I made a stop to check on the driver.\""), .direct("What did you learn about {D}'s license?", "\"The DMV record showed it was revoked because of a prior DWI. {D} should not have been driving at all.\""), .direct("What did the roadside test show?", "\"A reading of 0.10 on the roadside breath test, above the legal limit of 0.08.\""), .direct("What did you see that led you to stop {D}'s car?", "\"The car drifted across the line twice and then braked hard for no reason at a stop sign. I turned on my lights at about 11:45.\""), .direct("What was {D}'s condition when you approached the window?", "\"Bloodshot eyes, slurred speech, and the smell of alcohol. {D} said there had been a wedding reception earlier and that the friend who was driving had left.\""), .direct("How was the roadside test administered?", "\"I had {D} blow into a portable device after a fifteen-minute observation. It read 0.10, and I arrested {D} and took {D.him} to the station.\""), .cross("{D} said a friend was supposed to drive, didn't {D.he}?", "\"Yes. But the friend was not there when I arrived, so I could not speak to anyone.\""), .cross("{D} had only a drink or two, didn't {D.he}?", "\"That is what {D} said. A 0.10 is hard to reach with one drink, in my experience.\""), .cross("Roadside machines can be off, can't they?", "\"They can have a margin of error. That is why a more reliable test would follow.\""), .cross("Did you run a second test at the station?", "\"The station machine was out of service that night, so the roadside reading is the only breath result I have.\""), .cross("Did {D} perform the field sobriety tests well?", "\"Not well. {D} missed a few steps on the walk-and-turn and swayed on the one-leg stand. A couple of those can be affected by uneven ground.\"")],
        theory: ("{D} drove drunk with a revoked license.", "A friend who left."),
        allocution: "\"I made a bad choice.\"",
        truths: ("The friend was never at the reception.", "A groomsman had promised to drive {DL} home and left early without telling anyone."),
        defendant: [.direct("Had you been drinking at the reception?", "\"Some. I had a few drinks, but I did not feel drunk. I was celebrating with friends.\""), .direct("Why did you drive?", "\"A friend was supposed to drive me home. The friend left early without telling me, and I had no other way.\""), .direct("Did you know your license was revoked?", "\"Yes, I knew. It was from before. I should not have driven, and I know that.\""), .direct("Tell us what you remember about the reception.", "\"It was a friend's wedding. I had a few drinks over the evening, danced, and had cake. A friend had promised to drive me home.\""), .direct("What happened with your ride?", "\"When I looked for my friend after the last dance, they'd already left. I called twice and got no answer.\""), .direct("Why did you decide to drive yourself?", "\"It was late, I was far from home, and I didn't have money for a taxi. I know I made a bad choice.\""), .cross("You chose to drive with a revoked license, didn't you?", "\"I did. I was stuck. I did not have another ride, and I made a bad choice.\""), .cross("The machine read 0.10. Do you dispute it?", "\"I think the machine was off. I did not feel that impaired, but I understand the number.\""), .cross("You were swerving on the road, weren't you?", "\"I may have drifted a little. I was tired, and it was late.\""), .cross("You knew your license was revoked. Why drive at all?", "\"I was stuck, and I thought it was only a few miles. I know that isn't a good excuse.\""), .cross("The machine read 0.10. Do you say you were not over the limit?", "\"I felt okay to drive, but I'm not going to argue with the machine. I know I'd had more than a couple.\"")],
