        role: "Passenger",
        exam: [.direct("Where were you on {DATE} at about 5 p.m.?", "\"On a county bus heading home from work. I was tired and fell asleep in a window seat around 5:10.\""), .direct("What happened while you slept?", "\"I woke up at the last stop and my phone was gone. It had been in my hand or on the seat next to me.\""), .direct("What was the phone worth?", "\"About $800. It was only a year old and in a good case, and it held photos and my work contacts.\""), .direct("How did you find who took it?", "\"The bus camera showed {D}, sitting behind me, reach over and lift the phone from the seat around 5:30.\""), .direct("What did {D} do after that?", "\"{D} got off one stop early, at about 5:40, with the phone. I didn't know until I saw the video.\""), .direct("How did you track the phone?", "\"I used a location app. It showed the phone near {D}'s home that evening.\""), .cross("Isn't it true you were asleep when it happened?", "\"Yes. I didn't see or feel anything. I only know what the camera shows.\""), .cross("Could the phone have fallen to the floor?", "\"It's possible it slipped from my lap. I don't know where exactly it was when I fell asleep.\""), .cross("Did anyone speak to {D} on the bus?", "\"Not that I saw. {D} sat quietly and got off at a regular stop.\""), .cross("Did anyone return the phone to the bus company?", "\"I was told a phone was turned in to the lost-and-found log that evening. I haven't confirmed whether it was mine.\""), .cross("Did you have a lock on your phone?", "\"Yes, a passcode. Nobody could have read my messages without it.\"")],
        theory: ("{D} took a sleeping rider's phone.", "A phone picked up to return."),
