        state: [E(.document, 3, "Wire Receipt", "$2,400 picked up by {D} with ID."), E(.video, 3, "Store Camera", "{D} collects cash at the counter.")],
        defense: [E(.statement, 1, "Courier", "{DL} says {D.he} was paid to collect packages.")],
        role: "Victim",
        exam: [.direct("What did the caller say to you?", "\"The caller said to be my grandson, in jail and needing bail. The voice sounded upset, and I was frightened.\""), .direct("What did you do?", "\"I wired $2,400. I was told it was urgent, and I did not stop to think.\""), .direct("Who picked up the money?", "\"I learned later that {D} collected it at a store. The receipt shows {D}'s ID, and the store camera recorded it.\""), .direct("Tell the jury how the call started and what you thought.", "\"The phone rang mid-morning and a voice said, 'Grandma, it's me.' I thought it was my grandchild, and I was frightened by how upset the caller sounded.\""), .direct("What did the caller ask you to do?", "\"To go to a store and wire $2,400 right away for bail, and not to tell anyone. The caller said I'd be helping my grandchild stay out of trouble.\""), .direct("When did you learn it was a scam?", "\"About an hour later, when I called a relative of my grandchild. I was told my grandchild was at school and had never been arrested.\""), .cross("You never saw {D}, did you?", "\"No. I have never met {D}. I only know what deputies told me.\""), .cross("You were told it was urgent, weren't you?", "\"Yes. The caller told me to hurry and not to tell anyone. That is the part that scared me.\""), .cross("Did {D} speak to you?", "\"No. I never spoke to {D}. The caller was a different voice.\""), .cross("Did you ever hear {D}'s voice?", "\"No. I've never spoken to {D}. The only voice I heard was the caller's, and it sounded like a young person.\""), .cross("Did the caller give you a name for who would pick up the wire?", "\"Yes, a name that I wrote down. It wasn't {D}'s name, so I don't know how {D} got the money.\"")],
        theory: ("{D} collected the stolen wire.", "A courier who did not know."),
        allocution: "\"I'm sorry. I knew it was wrong.\"",
        truths: ("{DL} had picked up wires from four other victims.", "The man who hired {DL} for 'package pickups' was arrested and called {DL} a dupe."),
        defendant: [.direct("Did you know this was a scam?", "\"No. I did not know. I thought I was collecting packages for a job.\""), .direct("Why did you collect the money?", "\"I was told it was a job picking up packages. I was paid for each pickup, and I did not ask what was inside.\""), .direct("Did you meet the person who hired you?", "\"Only by phone and by text. I did what was asked, and I never saw a face.\""), .direct("Describe the job you took in your own words.", "\"Someone I met online offered ten percent to pick up packages and wire receipts at stores and deliver them. It sounded like easy money.\""), .direct("What did you think you were collecting?", "\"I thought they were payments from a business. I was told not to open anything and to send a photo of each receipt.\""), .direct("How many pickups did you do?", "\"Five, I think. I used my own ID each time and never hid my face.\""), .cross("You picked up wires from four other people, didn't you?", "\"Yes, I thought they were packages. I know now that was a mistake.\""), .cross("You were paid ten percent. Did that seem odd?", "\"It seemed like good pay for easy work. I did not think hard about it.\""), .cross("You used your own ID at the store, didn't you?", "\"I did. I thought I was doing a legitimate job and did not hide anything.\""), .cross("You were paid ten percent for picking up cash from strangers. Didn't that seem odd?", "\"It did occur to me, but I needed the money and I wanted to believe it was legal.\""), .cross("You didn't ask who the senders were?", "\"No. I wish I had. I was told it was a business and I didn't push.\"")],
        openings: ("A 79-year-old received a call from someone claiming to be a grandson in jail and wired $2,400. The money was picked up by {D} at a store, with ID, and a camera recorded it.", "The defense will present evidence that {D} was hired to collect packages and never knew the money came from a scam. {D} used a real ID and hid nothing."),
        closings: ("A frightened grandparent, $2,400, and {D} at the counter collecting it, four more times for other victims. Taking ten percent of an elder's panic is not a job.", "{D} was a pawn in a scheme, hired by someone who has been arrested. {D} used a real ID. The State must prove {D} knew, and there is no proof of that."),
        timeline: [(0, "10 a.m.: the call."), (0, "11 a.m.: {V} wires the money."), (0, "12 p.m.: {DL} collects it.")],
        identified: "A wire receipt and a camera.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "I was so ashamed.")

